PREREQUISITES=[]
def sha(path): return hashlib.sha256(path.read_bytes()).hexdigest()
for row in ROWS:
    path=ROOT/row['path']
    actual=sha(path) if path.exists() else None
    if actual!=row['before']: raise SystemExit('Source guard failed: '+row['path']+' actual='+str(actual))
for row in PREREQUISITES:
    path=ROOT/row['path']
    if not path.is_file() or sha(path)!=row['after']: raise SystemExit('Prerequisite source guard failed: '+row['path'])
blob=gzip.decompress(base64.b64decode(''))
if hashlib.sha256(blob).hexdigest()!='f72108cd21aae0e09a3e0499b6e377029d73a5f35b7fca4e27c8a11202b5a472': raise SystemExit('Patch transport hash mismatch')
patch=ROOT/'output/session-10290244/headers-codec-reviewed.patch'
patch.parent.mkdir(parents=True,exist_ok=True)
if patch.exists() and patch.read_bytes()!=blob: raise SystemExit('Refusing to replace a different patch receipt')
patch.write_bytes(blob)
subprocess.run(['git','apply','--check',str(patch)],check=True)
subprocess.run(['git','apply',str(patch)],check=True)
for row in ROWS:
    if sha(ROOT/row['path'])!=row['after']: raise SystemExit('Installed source hash mismatch: '+row['path'])
print(json.dumps({'installed':len(ROWS),'patch_sha256':hashlib.sha256(blob).hexdigest(),'files':ROWS}))
